/* BUG-1016 (2026-09-14): THE bounds for a bounded walk, tied to the limits that already
 * refuse the program before the walk runs — so a cap at or above them is closed BY
 * CONSTRUCTION and needs no conservative answer of its own (it still gets one).
 *
 *   ZER_EXPR_WALK_MAX  — a walk over an EXPRESSION tree. check_expr refuses any
 *                        expression deeper than ZER_EXPR_NESTING_LIMIT (1000, VST-verified
 *                        in src/safety/comptime_rules.c). The PARSER's 256 is NOT that
 *                        bound: a left-associative chain `g + 1 + 1 + ...` parses
 *                        iteratively, so a 300-term chain reaches AST depth 300 under the
 *                        parser's counter — measured: rmw_value_source_global's old cap of
 *                        256 lost the taint on `u32 t = g + 1 + ... (300); g = t;` and an
 *                        ISR read-modify-write was accepted.
 *   ZER_STMT_NEST_MAX  — a walk over STATEMENT nesting (the parser's "nesting too deep
 *                        (limit 64)"). Note a walk that counts BOTH the block and the
 *                        statement inside it sees ~2 levels per source level.
 *   ZER_TYPE_NEST_MAX  — a walk over a TYPE's syntactic wrappers (pointer / array /
 *                        optional; the parser's "type nesting too deep (limit 256)").
 *                        By-value STRUCT nesting has NO syntactic limit — a type walk
 *                        through struct fields must still round toward reject past its
 *                        cap (BUG-977), or use a visited set. */
#define ZER_EXPR_WALK_MAX (ZER_EXPR_NESTING_LIMIT + 8)
#define ZER_STMT_NEST_MAX 64
#define ZER_TYPE_NEST_MAX 256
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdarg.h>

/* Convert checker's per-Symbol flags to a region tag. */
static int zer_sym_region_tag(bool is_local_derived, bool is_arena_derived) {
    if (is_local_derived) return ZER_REGION_LOCAL;
    if (is_arena_derived) return ZER_REGION_ARENA;
    return ZER_REGION_STATIC;
}

/* GAP-8 (BUG-737, 2026-06-10): does this type carry a RAW data pointer at any
 * nesting depth? Used to taint non-keep BY-VALUE struct/union params with
 * is_nonkeep_derived — the struct analog of the non-keep pointer-param rule
 * (a by-value struct's pointer fields have caller-unknown provenance: could
 * be &local or arena-derived; persisting the struct must require 'keep').
 * Counts: *T, *opaque, [*]T / []T (slice data pointer), and ?-wrapped /
 * array-of / nested-struct-or-union-of those (depth-limited 32, same pattern
 * as contains_move_struct_field_depth). Does NOT count: funcptrs (code
 * addresses, global by nature) and Handle (u64 index, not an address).
 * If-chain (not switch) so the walker-default audit is unaffected;
 * type_dispatch_kind keeps the distinct-unwrap CI gate green. */
static bool type_carries_data_pointer(Type *t, int depth) {
    /* BUG-976: past the cap the answer is UNKNOWN, and the conservative reading of
     * "does this carry a pointer?" is YES. Returning false here said "no pointer",
     * which is the ACCEPT direction — a deeply nested carrier walked out of the rule. */
    if (depth > 32) return true;
    if (!t) return false;
    TypeKind k = type_dispatch_kind(t);
    Type *u = type_unwrap_distinct(t);
    if (!u) return false;
    if (k == TYPE_POINTER || k == TYPE_OPAQUE || k == TYPE_SLICE) return true;
    if (k == TYPE_OPTIONAL)
        return type_carries_data_pointer(u->optional.inner, depth + 1);
    if (k == TYPE_ARRAY)
        return type_carries_data_pointer(u->array.inner, depth + 1);
    if (k == TYPE_STRUCT) {
        for (uint32_t i = 0; i < u->struct_type.field_count; i++) {
            if (type_carries_data_pointer(u->struct_type.fields[i].type, depth + 1))
                return true;
        }
        return false;
    }
    if (k == TYPE_UNION) {
        for (uint32_t i = 0; i < u->union_type.variant_count; i++) {
            if (type_carries_data_pointer(u->union_type.variants[i].type, depth + 1))
                return true;
        }
        return false;
    }
    return false;
}

/* Does this type CARRY a Handle at any nesting depth?
 *
 * Sibling of type_carries_data_pointer, deliberately SEPARATE rather than an
 * extension of it: a Handle is an INDEX (u64), not a pointer into a frame, so
 * folding TYPE_HANDLE into the data-pointer predicate would over-reject at the
 * escape sinks that legitimately ask "does this carry a reference into my
 * stack frame?". Two questions, two predicates.
 *
 * Recurses optional / array / struct / union and unwraps distinct, so every
 * member of the "wrapper hides the inner kind" family is covered by one call
 * (CLAUDE.md, the class killed by tools/audit_carrier_dispatch.sh). */
static bool type_carries_handle(Type *t, int depth) {
    if (depth > 32) return true;   /* BUG-976: unknown -> assume it carries one */
    if (!t) return false;
    TypeKind k = type_dispatch_kind(t);
    Type *u = type_unwrap_distinct(t);
    if (!u) return false;
    if (k == TYPE_HANDLE) return true;
    if (k == TYPE_OPTIONAL)
        return type_carries_handle(u->optional.inner, depth + 1);
    if (k == TYPE_ARRAY)
        return type_carries_handle(u->array.inner, depth + 1);
    if (k == TYPE_STRUCT) {
        for (uint32_t i = 0; i < u->struct_type.field_count; i++) {
            if (type_carries_handle(u->struct_type.fields[i].type, depth + 1))
                return true;
        }
        return false;
    }
    if (k == TYPE_UNION) {
        for (uint32_t i = 0; i < u->union_type.variant_count; i++) {
            if (type_carries_handle(u->union_type.variants[i].type, depth + 1))
                return true;
        }
        return false;
    }
    return false;
}

/* BUG-1260: does this type hold a `move struct` anywhere (fields, elements,
 * optional payload, union variants)? Past the cap: assume it does. */
static bool type_carries_move_struct(Type *t, int depth) {
    if (depth > 256) return true;
    if (!t) return false;
    TypeKind k = type_dispatch_kind(t);
    Type *u = type_unwrap_distinct(t);
    if (!u) return false;
    if (k == TYPE_OPTIONAL) return type_carries_move_struct(u->optional.inner, depth + 1);
    if (k == TYPE_ARRAY) return type_carries_move_struct(u->array.inner, depth + 1);
    if (k == TYPE_STRUCT) {
        if (u->struct_type.is_move) return true;
        for (uint32_t i = 0; i < u->struct_type.field_count; i++)
            if (type_carries_move_struct(u->struct_type.fields[i].type, depth + 1)) return true;
        return false;
    }
    if (k == TYPE_UNION) {
        for (uint32_t i = 0; i < u->union_type.variant_count; i++)
            if (type_carries_move_struct(u->union_type.variants[i].type, depth + 1)) return true;
        return false;
    }
    return false;
}

/* Forward: the SCOPED constant evaluator (defined below with the other const
 * machinery). Needed up here by the size fold, which must resolve a `const`
 * identifier — the non-scoped evaluator cannot. */
static int64_t eval_const_expr_scoped(Checker *c, Node *n);

/* BUG-1033: the builtin-container type kinds, by display name (NULL for any other
 * kind). Exhaustive so a new TypeKind is a build failure, not a silent "not a
 * container". */
static const char *builtin_container_kind_name(int kind) {
    switch ((TypeKind)kind) {
    case TYPE_ARENA:     return "Arena";
    case TYPE_BARRIER:   return "Barrier";
    case TYPE_SEMAPHORE: return "Semaphore";
    case TYPE_POOL:      return "Pool";
    case TYPE_SLAB:      return "Slab";
    case TYPE_RING:      return "Ring";
    case TYPE_VOID: case TYPE_BOOL: case TYPE_U8: case TYPE_U16: case TYPE_U32:
    case TYPE_U64: case TYPE_USIZE: case TYPE_I8: case TYPE_I16: case TYPE_I32:
    case TYPE_I64: case TYPE_F32: case TYPE_F64: case TYPE_POINTER: case TYPE_OPTIONAL:
    case TYPE_SLICE: case TYPE_ARRAY: case TYPE_STRUCT: case TYPE_ENUM: case TYPE_UNION:
    case TYPE_FUNC_PTR: case TYPE_OPAQUE: case TYPE_HANDLE: case TYPE_DISTINCT:
    case TYPE_UINT: case TYPE_SINT:
        return NULL;
    }
    return NULL;
}

/* BUG-873: evaluate a declared SIZE/COUNT expression, resolving `const`
 * identifiers, and FOLD THE RESULT IN PLACE.
 *
 * Four sites asked this question — array size, Pool count, Ring count,
 * Semaphore count — each with its own `eval_const_expr(expr)` call, and all
 * four used the NON-scoped evaluator, which by construction cannot resolve a
 * NODE_IDENT. So
 *
 *     const u32 CAP = 4;   u8[CAP] buf;   Pool(Slot, CAP) p;
 *
 * — the most idiomatic firmware declaration there is — was rejected with "must
 * be a compile-time constant", naming a constant.
 *
 * The IN-PLACE rewrite is the load-bearing part. The EMITTER re-resolves the
 * same TypeNode with the non-scoped evaluator, so teaching only the checker
 * leaves the emitter still failing — silently, sizing the array 0 and making
 * `@size(u8[CAP])` yield 0. A compile-only test passes that. Trading an
 * over-rejection for a wrong answer is worse than the over-rejection, so the
 * two halves must see the same value, and the only way to guarantee that is for
 * there to be one value. tests/zer/const_compile_time_sizes.zer therefore
 * asserts the sizes at RUNTIME.
 *
 * Each caller keeps its own range predicate (> 0 for array/Pool/Ring, >= 0 for
 * Semaphore) and its own message. */
static void ct_type_width(Type *t, uint16_t *bits, bool *is_signed);
static int64_t ct_wrap(int64_t v, uint16_t bits, bool is_signed);
static Type *typemap_get(Checker *c, Node *node);
/* BUG-1209: does this constant expression read a TYPED value (a const, a call)?
 * A pure-literal expression has no declared width — its literal typing is
 * contextual (`err = -1` in an enum is typed u32 by default) — so only an
 * expression over typed values is wrapped to its checked type. Answering "no"
 * for an unlisted kind keeps the untyped fold, the pre-BUG-1209 behaviour. */
static bool const_expr_reads_typed_value(Node *e, int depth) {
    if (!e || depth > ZER_EXPR_WALK_MAX) return false;
    if (e->kind == NODE_IDENT || e->kind == NODE_CALL) return true;
    if (e->kind == NODE_UNARY) return const_expr_reads_typed_value(e->unary.operand, depth + 1);
    if (e->kind == NODE_TYPECAST) return const_expr_reads_typed_value(e->typecast.expr, depth + 1);
    if (e->kind == NODE_BINARY)
        return const_expr_reads_typed_value(e->binary.left, depth + 1) ||
               const_expr_reads_typed_value(e->binary.right, depth + 1);
    return false;
}
static int64_t eval_decl_size_expr(Checker *c, Node *e) {
    if (!e) return CONST_EVAL_FAIL;
    /* BUG-1209: a size EXPRESSION over typed values has a checked type, and its
     * value is the fold wrapped into that type — `T[SMALL + SMALL]` over `const u8
     * SMALL = 200` is 144 in ZER's u8 arithmetic. The untyped fold said 400. */
    uint16_t wb = 0; bool ws = false;
    if (const_expr_reads_typed_value(e, 0))
        ct_type_width(typemap_get(c, e), &wb, &ws);
    int64_t val = eval_const_expr(e);
    if (val != CONST_EVAL_FAIL) return ct_wrap(val, wb, ws);
    int64_t sval = eval_const_expr_scoped(c, e);
    if (sval == CONST_EVAL_FAIL) return CONST_EVAL_FAIL;
    sval = ct_wrap(sval, wb, ws);
    e->kind = NODE_INT_LIT;
    e->int_lit.value = (uint64_t)sval;
    return sval;
}

/* Fold a declaration's `const` / `volatile` keywords into the resolved slice or
 * pointer TYPE.
 *
 * BUG-872. This was written out longhand at TWO sites (register_decl and the
 * body-check var-decl case) and MISSING at a third — the pass-2 global
 * initializer check, which re-resolved `decl->var_decl.type` raw. So pass 1
 * registered `BANNER` as `const [*]u8` and pass 2 compared a MUTABLE `[*]u8`
 * target against a const initializer:
 *
 *     const [*]u8 BANNER = "boot ok";
 *     error: cannot initialize 'BANNER' of type '[]u8' with '[]u8'
 *
 * — the single most common firmware global there is, not declarable at all, and
 * reported with the SAME type printed on both sides, because `type_name` does
 * not render qualifiers. A message that cannot express the difference it
 * reports is the tell that the two sides were computed differently.
 *
 * One helper now, called at all three. `is_const`/`is_volatile` are passed
 * rather than read off a Node so the qualifier source stays explicit. */
static Type *fold_decl_qualifiers(Checker *c, Type *type, bool is_const, bool is_volatile) {
    if (!type) return type;
    /* The const branch does NOT unwrap distinct, deliberately. Rebuilding the
     * type from the unwrapped inner would DISCARD the distinct wrapper's nominal
     * identity, and `const MyPtr cg = g;` on a `distinct typedef *u32 MyPtr`
     * would then stop type-checking against `MyPtr`. (Caught by
     * tests/zer/distinct_const_read_ok when the first draft of this helper
     * unwrapped here; a const distinct is already const-by-declaration through
     * Symbol.is_const, so nothing is lost by leaving the type alone.) */
    if (is_const) {
        if (type->kind == TYPE_SLICE && !type->slice.is_const)
            type = type_const_slice(c->arena, type->slice.inner);
        else if (type->kind == TYPE_POINTER && !type->pointer.is_const)
            type = type_const_pointer(c->arena, type->pointer.inner);
    }
    if (is_volatile) {
        Type *eff = type_unwrap_distinct(type);
        if (eff && eff->kind == TYPE_SLICE && !eff->slice.is_volatile) {
            type = type_volatile_slice(c->arena, eff->slice.inner);
            if (is_const) type->slice.is_const = true;
        } else if (eff && eff->kind == TYPE_POINTER && !eff->pointer.is_volatile) {
            Type *vp = type_pointer(c->arena, eff->pointer.inner);
            vp->pointer.is_volatile = true;
            if (eff->pointer.is_const || is_const) vp->pointer.is_const = true;
            type = vp;
        }
    }
    return type;
}

/* BUG-868: does a field DECLARED with this syntax keep its storage INLINE in
 * the enclosing struct — so a containment edge through it counts toward an
 * infinite size — or does it hold a reference, making the edge finite?
 *
 * A no-`default:` switch rather than an if-chain on purpose: this is the
 * question the whole cycle guard turns on, every kind deserves an explicit
 * answer, and `-Werror=switch` then makes a new TypeNodeKind a build failure
 * instead of a silent default. (It also keeps the type-dispatch audit quiet,
 * which greps for `->kind ==` comparisons and cannot tell a considered
 * syntactic peel from the GAP-F distinct-unwrap bug class.)
 *
 * Erring toward INLINE is the safe direction here: a mis-classified indirect
 * edge can only over-reject a cycle, whereas a mis-classified inline edge
 * restores the compiler crash this guard exists to prevent. */
static bool tynode_keeps_storage_inline(TypeNode *t, int depth) {
    /* BUG-1016: the syntactic wrappers this walk peels are bounded by the parser at
     * ZER_TYPE_NEST_MAX, so the cap is unreachable; past it the answer rounds toward
     * INLINE — the direction the comment above names as safe. The old `> 32 -> false`
     * was the unsafe direction by that same reasoning. */
    if (!t) return false;
    if (depth > ZER_TYPE_NEST_MAX) return true;
    switch (t->kind) {
    /* Wrappers that keep the element inline — peel and re-ask. */
    case TYNODE_ARRAY:    return tynode_keeps_storage_inline(t->array.elem, depth + 1);
    case TYNODE_CONST:
    case TYNODE_VOLATILE: return tynode_keeps_storage_inline(t->qualified.inner, depth + 1);
    /* Inline storage of a user type — the edges that can close a size cycle. */
    case TYNODE_CONTAINER:
    case TYNODE_NAMED:    return true;
    /* References: the pointee lives elsewhere, so the size is finite. */
    case TYNODE_POINTER: case TYNODE_OPTIONAL: case TYNODE_SLICE:
    case TYNODE_FUNC_PTR:
        return false;
    /* Builtins hold their own storage but can never BE a container stamp, so
     * they cannot close a cycle back onto one. */
    case TYNODE_POOL: case TYNODE_RING: case TYNODE_ARENA: case TYNODE_BARRIER:
    case TYNODE_HANDLE: case TYNODE_SLAB: case TYNODE_SEMAPHORE:
        return false;
    /* Primitives — likewise. */
    case TYNODE_U8: case TYNODE_U16: case TYNODE_U32: case TYNODE_U64:
    case TYNODE_I8: case TYNODE_I16: case TYNODE_I32: case TYNODE_I64:
    case TYNODE_USIZE: case TYNODE_F32: case TYNODE_F64:
    case TYNODE_BOOL: case TYNODE_VOID: case TYNODE_OPAQUE:
        return false;
    }
    return false;
}

/* ---------------------------------------------------------------------------
 * BUG-869: is any NODE anywhere in a global initializer a form that cannot
 * lower to a compile-time constant?
 *
 * The three guards this replaces were all TOP-LEVEL kind tests on the
 * initializer root — `ginit->kind == NODE_CALL`, and two on
 * `ginit->kind == NODE_INTRINSIC`. So ONE wrapper defeated all three:
 *
 *     u32 G = @cpu_model_id() + 1;    // binary  -> accepted
 *     u32 G = (u32)f();               // cast    -> accepted
 *     u32 G = -f();                   // unary   -> accepted
 *     u32 G = @popcount(f());         // nested  -> accepted
 *
 * and the failure landed on GCC, naming a line in a generated .c the user never
 * opened. This is the exact sibling of BUG-842, which split the `arg_count`
 * precondition out of these checks but left the top-level-kind SHAPE — same
 * rule, second axis.
 *
 * The verdict logic is unchanged; what changes is that it is asked at EVERY
 * node instead of only the root. The recursion uses a no-`default:` switch so
 * `-Werror=switch` makes a new NodeKind a build failure rather than a silent
 * coverage gap (the walker discipline in CLAUDE.md).
 * ------------------------------------------------------------------------- */

/* Verdict for ONE node. Returns a reason string, or NULL if this node is fine.
 * `type` is the DECLARED type of the global, needed only for the non-native
 * uN/iN @truncate case. */
static const char *global_init_node_reason(Node *n, Type *type) {
    if (!n) return NULL;
    if (n->kind == NODE_CALL && !n->call.is_comptime_resolved)
        return "cannot call functions at global scope";
    if (n->kind != NODE_INTRINSIC) return NULL;

    const char *gn = n->intrinsic.name;
    uint32_t gl = (uint32_t)n->intrinsic.name_len;

    /* Bit-query / byte-swap: constant-foldable only with a foldable argument.
     * NODE_FIELD is skipped to avoid over-rejecting an enum constant (State.x),
     * which IS a C constant but which eval_const_expr cannot see. */
    if (n->intrinsic.arg_count >= 1 && n->intrinsic.args[0] &&
        n->intrinsic.args[0]->kind != NODE_FIELD) {
        int is_bitq =
            (gl == 8 && memcmp(gn, "popcount", 8) == 0) ||
            (gl == 3 && memcmp(gn, "ctz", 3) == 0) ||
            (gl == 3 && memcmp(gn, "clz", 3) == 0) ||
            (gl == 3 && memcmp(gn, "ffs", 3) == 0) ||
            (gl == 6 && memcmp(gn, "parity", 6) == 0) ||
            (gl == 7 && (memcmp(gn, "bswap16", 7) == 0 ||
                         memcmp(gn, "bswap32", 7) == 0 ||
                         memcmp(gn, "bswap64", 7) == 0));
        if (is_bitq && eval_const_expr(n->intrinsic.args[0]) == CONST_EVAL_FAIL)
            return "requires a constant argument at global scope";
    }

    /* Forms that can NEVER appear in a file-scope initializer, whatever their
     * arguments: they lower to a ({...}) statement-expression or a runtime call.
     * @truncate folds to a constant `(T)val` cast for a NATIVE width only. */
    bool tgt_nonnative_intn = false;
    {
        TypeKind tk = type_dispatch_kind(type); /* unwraps distinct, NULL-safe */
        if (tk == TYPE_UINT || tk == TYPE_SINT) {
            uint32_t nb = type_unwrap_distinct(type)->intn.bits;
            tgt_nonnative_intn = !(nb == 8 || nb == 16 || nb == 32 || nb == 64 || nb == 128);
        }
    }
    bool is_atomic = (gl >= 7 && memcmp(gn, "atomic_", 7) == 0);
    bool is_runtime_read =
        (gl == 6 && memcmp(gn, "expect", 6) == 0) ||
        (gl >= 8 && memcmp(gn, "port_in", 7) == 0) ||
        (gl >= 4 && memcmp(gn, "cpu_", 4) == 0) ||
        (gl >= 4 && memcmp(gn, "mmu_", 4) == 0) ||
        (gl >= 4 && memcmp(gn, "tlb_", 4) == 0) ||
        (gl >= 6 && memcmp(gn, "cache_", 6) == 0) ||
        (gl == 5 && memcmp(gn, "probe", 5) == 0);
    if (is_atomic || is_runtime_read ||
        (gl == 8 && memcmp(gn, "saturate", 8) == 0) ||
        (gl == 7 && memcmp(gn, "bitcast", 7) == 0) ||
        (gl == 8 && memcmp(gn, "truncate", 8) == 0 && tgt_nonnative_intn) ||
        (gl == 4 && (memcmp(gn, "addc", 4) == 0 ||
                     memcmp(gn, "subb", 4) == 0 ||
                     memcmp(gn, "mulw", 4) == 0)))
        return "does not lower to a compile-time-constant value at global scope";
    return NULL;
}

/* Walk the whole initializer tree; report the FIRST offending node. `*bad` is
 * set to that node so the caller can name the construct. */
/* BUG-1127: `c` resolves identifiers — a MUTABLE global named anywhere in the tree
 * is not a compile-time constant (BUG-997 checked only a bare top-level ident, so
 * `u32 x = m + 1;` and `S s = { .f = m };` reached GCC as "initializer element is
 * not constant" against the generated file). */
static Symbol *global_decl_lookup(Checker *c, const char *name, uint32_t name_len);
static void check_suspend_in_union_capture(Checker *c, Node *node, const char *what);
static void check_suspend_in_once(Checker *c, Node *node, const char *what);
static const char *global_init_scan(Checker *c, Node *n, Type *type, int depth, Node **bad) {
    if (!n) return NULL;
    /* BUG-1016: NULL past the cap read as "nothing offending", so a call hidden 200
     * terms down a flat chain (`u32 g = f() + 1 + ... ;`) passed this scan and reached
     * GCC as an "initializer element is not constant" against a generated file. The
     * cap is now above check_expr's own bound (closed by construction) and past it
     * the answer is an offence, not an absence. */
    if (depth > ZER_EXPR_WALK_MAX) {
        *bad = n;
        return "nests deeper than the constant-initializer walk follows";
    }
    const char *r = global_init_node_reason(n, type);
    if (r) { *bad = n; return r; }
    #define GI(x) do { const char *_r = global_init_scan(c, (x), type, depth+1, bad); \
                       if (_r) return _r; } while (0)
    switch (n->kind) {
    case NODE_BINARY: GI(n->binary.left); GI(n->binary.right); break;
    case NODE_UNARY:
        if (n->unary.op == TOK_AMP) {
            /* `&g`, `&g.f`, `&g[2]` are ADDRESS constants: the root names the
             * object, it does not read it. An index expression is still a read. */
            Node *r = n->unary.operand;
            while (r && (r->kind == NODE_FIELD || r->kind == NODE_INDEX)) {
                if (r->kind == NODE_INDEX) GI(r->index_expr.index);
                r = (r->kind == NODE_FIELD) ? r->field.object : r->index_expr.object;
            }
            if (r && r->kind != NODE_IDENT) GI(r);
            break;
        }
        GI(n->unary.operand);
        break;
    case NODE_TYPECAST: GI(n->typecast.expr); break;
    case NODE_ORELSE: GI(n->orelse.expr); GI(n->orelse.fallback); break;
    case NODE_INDEX: {
        /* Indexing READS the element. A global ARRAY named bare is its address
         * (see NODE_IDENT), so the root of an index chain is checked here, as a
         * read, rather than by the identifier arm. */
        Node *r = n;
        while (r && (r->kind == NODE_INDEX || r->kind == NODE_FIELD))
            r = (r->kind == NODE_INDEX) ? r->index_expr.object : r->field.object;
        if (c && r && r->kind == NODE_IDENT) {
            Symbol *gs = global_decl_lookup(c, r->ident.name, (uint32_t)r->ident.name_len);
            if (gs && !gs->is_function && !gs->is_const && gs->func_node &&
                gs->func_node->kind == NODE_GLOBAL_VAR) {
                *bad = r;
                return "names a MUTABLE global, which is not a compile-time constant";
            }
        }
        GI(n->index_expr.object); GI(n->index_expr.index);
        break;
    }
    case NODE_SLICE: GI(n->slice.object); GI(n->slice.start); GI(n->slice.end); break;
    case NODE_FIELD:
        /* `arr.len` of a FIXED array is its size — a constant, not a read. */
        if (c && n->field.field_name_len == 3 &&
            memcmp(n->field.field_name, "len", 3) == 0 && n->field.object &&
            n->field.object->kind == NODE_IDENT) {
            Symbol *os = global_decl_lookup(c, n->field.object->ident.name,
                                            (uint32_t)n->field.object->ident.name_len);
            if (os && os->type && type_dispatch_kind(os->type) == TYPE_ARRAY) break;
        }
        /* BUG-1219: a FIELD read of a global VARIABLE is a read of that variable,
         * const or not — C evaluates no object at file scope, and `u32 x = cg.a;`
         * over `const C cg = { .a = 5 };` emitted `(struct C){ .a = 5U }.a`,
         * "initializer element is not constant". (An enum's `Color.red` names a
         * TYPE, and `&g.f` is an address — both are handled elsewhere.) */
        if (c && n->field.object) {
            Node *fr = n->field.object;
            while (fr && (fr->kind == NODE_FIELD || fr->kind == NODE_INDEX))
                fr = (fr->kind == NODE_FIELD) ? fr->field.object : fr->index_expr.object;
            if (fr && fr->kind == NODE_IDENT) {
                Symbol *fs = global_decl_lookup(c, fr->ident.name, (uint32_t)fr->ident.name_len);
                if (fs && !fs->is_function && fs->func_node &&
                    fs->func_node->kind == NODE_GLOBAL_VAR) {
                    *bad = n;
                    return "reads a field of a global variable, which C cannot evaluate "
                           "at file scope (not even a const one)";
                }
            }
        }
        GI(n->field.object);
        break;
    case NODE_CALL:
        GI(n->call.callee);
        for (int i = 0; i < n->call.arg_count; i++) GI(n->call.args[i]);
        break;
    case NODE_INTRINSIC:
        for (int i = 0; i < n->intrinsic.arg_count; i++) GI(n->intrinsic.args[i]);
        break;
    case NODE_STRUCT_INIT:
        for (int i = 0; i < n->struct_init.field_count; i++)
            GI(n->struct_init.fields[i].value);
        break;
    /* value FIRST: `u32 G = (x = f());` is refused for the call (the specific
     * reason); `(x = 5)` is still refused, for naming the mutable `x`. */
    case NODE_ASSIGN: GI(n->assign.value); GI(n->assign.target); break;
    /* A global initializer is an EXPRESSION, so no statement kind can occur
     * below here. They are still descended rather than listed as no-op leaves:
     * the walker-field audit's rule is that an arm naming a kind must visit its
     * children, and honouring it costs nothing while keeping the walk TOTAL if
     * the AST ever changes shape. Mirrors zbi_scan_children. */
    case NODE_FILE: for (int i=0;i<n->file.decl_count;i++) GI(n->file.decls[i]); break;
    case NODE_FUNC_DECL: GI(n->func_decl.body); break;
    case NODE_INTERRUPT: GI(n->interrupt.body); break;
    case NODE_BLOCK: for (int i=0;i<n->block.stmt_count;i++) GI(n->block.stmts[i]); break;
    case NODE_IF: GI(n->if_stmt.cond); GI(n->if_stmt.then_body); GI(n->if_stmt.else_body); break;
    case NODE_FOR: GI(n->for_stmt.init); GI(n->for_stmt.cond); GI(n->for_stmt.step);
        GI(n->for_stmt.body); break;
    case NODE_WHILE: case NODE_DO_WHILE: GI(n->while_stmt.cond); GI(n->while_stmt.body); break;
    case NODE_SWITCH:
        GI(n->switch_stmt.expr);
        for (int i=0;i<n->switch_stmt.arm_count;i++) GI(n->switch_stmt.arms[i].body);
        break;
    case NODE_GLOBAL_VAR: case NODE_VAR_DECL: GI(n->var_decl.init); break;
    case NODE_RETURN: GI(n->ret.expr); break;
    case NODE_DEFER: GI(n->defer.body); break;
    case NODE_CRITICAL: GI(n->critical.body); break;
    case NODE_ONCE: GI(n->once.body); break;
    case NODE_AWAIT: GI(n->await_stmt.cond); break;
    case NODE_STATIC_ASSERT: GI(n->static_assert_stmt.cond); break;
    case NODE_SPAWN: for (int i=0;i<n->spawn_stmt.arg_count;i++) GI(n->spawn_stmt.args[i]); break;
    case NODE_EXPR_STMT: GI(n->expr_stmt.expr); break;
    /* exhaustive (no default:) — genuine leaves. A NEW NodeKind fails the build
     * under -Werror=switch, which is the point. */
    case NODE_STRUCT_DECL: case NODE_ENUM_DECL: case NODE_UNION_DECL:
    case NODE_TYPEDEF: case NODE_IMPORT: case NODE_CINCLUDE: case NODE_MMIO:
    case NODE_ASM:
        for (int i=0;i<n->asm_stmt.input_count;i++) GI(n->asm_stmt.inputs[i].expr);
        for (int i=0;i<n->asm_stmt.output_count;i++) GI(n->asm_stmt.outputs[i].expr);
        break;
    case NODE_CONTAINER_DECL: case NODE_BREAK: case NODE_CONTINUE:
    case NODE_GOTO: case NODE_LABEL: case NODE_YIELD:
    case NODE_INT_LIT: case NODE_FLOAT_LIT: case NODE_STRING_LIT:
    case NODE_CHAR_LIT: case NODE_BOOL_LIT: case NODE_NULL_LIT:
    case NODE_IDENT:
        if (c) {
            Symbol *gs = global_decl_lookup(c, n->ident.name, (uint32_t)n->ident.name_len);
            /* A global ARRAY named bare is its ADDRESS (array-to-slice/pointer
             * decay, `buf[0..2]`) — a constant. Reads of it are indexing, above;
             * copying a whole array into a global array is refused separately. */
            if (gs && !gs->is_function && !gs->is_const && gs->func_node &&
                gs->func_node->kind == NODE_GLOBAL_VAR &&
                !(gs->type && type_dispatch_kind(gs->type) == TYPE_ARRAY)) {
                *bad = n;
                return "names a MUTABLE global, which is not a compile-time constant";
            }
            /* BUG-1213: a static local's initializer runs ONCE, before main —
             * a name that lives in the function's frame has no value then. */
            if (c->gi_static_local) {
                Symbol *ls = scope_lookup(c->current_scope, n->ident.name,
                                          (uint32_t)n->ident.name_len);
                if (ls && ls != gs && !ls->is_function) {
                    *bad = n;
                    return "names a function-local variable, which has no value before "
                           "the program runs";
                }
            }
        }
        break;
    case NODE_CAST: case NODE_SIZEOF:
        break;
    }
    #undef GI
    return NULL;
}

/* "Does an uninitialised declaration of this type auto-zero into a NULL that
 * the type promises cannot be null?"
 *
 * BUG-866. This question was answered at TWO sites — the local NODE_VAR_DECL
 * and the global NODE_GLOBAL_VAR — as two hand-written copies, and they drifted:
 * the local copy grew a FUNC_PTR arm, the global one never did. So
 *
 *     *(u32, u32) -> u32 gop;          // global: accepted
 *     u32 main() { return gop(1, 2); } // emits a raw call through address 0
 *
 * compiled clean, while the identical declaration one scope deeper was rejected.
 * Two spellings of one program disagreeing is the tell for a drifted duplicate.
 *
 * Returns the offending effective type (so the caller can name it) or NULL.
 * `*is_func` distinguishes the two messages. Declaration level only: a non-null
 * pointer FIELD inside a struct is the same hazard but a much wider rule, and
 * that variant was measured at 34 affected corpus files, so it is deliberately
 * out of scope here — docs/limitations.md "a non-null `*T` / funcptr FIELD is
 * zero (NULL) wherever a struct is zero-initialized". The designated-initializer
 * spelling of it IS refused (BUG-1126, zero_value_nonnull_leaf). */
static Type *nonnull_zero_hole(Type *t, bool *is_func) {
    *is_func = false;
    if (!t) return NULL;
    Type *eff = type_unwrap_distinct(t);
    if (!eff) return NULL;
    if (!eff) return NULL;
    TypeKind k = type_dispatch_kind(eff);
    if (k == TYPE_POINTER) return eff;
    if (k == TYPE_FUNC_PTR) { *is_func = true; return eff; }
    return NULL;
}

/* Is this optional INNER type represented by a null sentinel (so the optional
 * IS the pointer at runtime and has no `.value` field)? Checker-side twin of
 * emitter.c's `is_null_sentinel`; kept identical, including the `*opaque`
 * exclusion (`_zer_opaque` is a struct, not a pointer). */
static bool is_null_sentinel_ck(Type *inner) {
    if (!inner) return false;
    Type *u = type_unwrap_distinct(inner);
    if (!u) return false;
    TypeKind k = type_dispatch_kind(u);
    if (k == TYPE_POINTER && u->pointer.inner &&
        type_dispatch_kind(u->pointer.inner) == TYPE_OPAQUE) return false;
    return k == TYPE_POINTER || k == TYPE_FUNC_PTR;
}


/* Does this type CARRY a pointer/slice/opaque whose pointee is NOT a shared
 * struct? That is the exact hazard the bare fire-and-forget spawn rule tests
 * ("non-shared pointer to spawn — data race"), lifted so it can be asked of a
 * by-value struct/union that merely CARRIES such a pointer in a field.
 *
 * The shared exemption mirrors the bare-arg logic EXACTLY: only a POINTER whose
 * pointee is a `shared struct` is exempt. A slice or opaque is a hazard
 * regardless, because neither carries the auto-lock discipline. */
/* Is a `volatile` global safe to EXEMPT from a concurrency data-race check?
 *
 * ONE query for both exemption sites — the spawned-thread scan
 * (scan_unsafe_global_access) and the ISR shared-global check
 * (check_interrupt_safety). They previously hand-rolled it, and the ISR copy was
 * never written at all: the spawn width guard landed 2026-08-03 and the ISR site
 * kept accepting a tearing store for another commit. Classic multi-site drift, so
 * the two now share this predicate and a hw-matrix row pins them together.
 *
 * The exemption exists for the SINGLE-WORD volatile-flag idiom — a plain store or
 * load of one machine word, which is atomic in practice on every real ISA. That
 * rationale is width-bounded, so enforce the bound: a scalar (integer / bool /
 * pointer) no wider than the target word. Anything wider lowers to MULTIPLE
 * stores, so a concurrent reader (another thread, or main preempted by an ISR)
 * can observe half of one write and half of another.
 *
 * NOT a claim that the exempted case is race-free: a single-word volatile access
 * still provides no ORDERING. It is the established embedded idiom, the
 * diagnostic already says volatile is not synchronization, and banning it is a
 * separate judgment call. A tearable multi-word access is not a judgment call. */
static bool volatile_global_exempt_from_race_check(Checker *c, Symbol *sym) {
    if (!c || !sym || !sym->is_volatile) return false;
    Type *vt = type_unwrap_distinct(sym->type);
    if (!vt) return false;
    TypeKind k = type_dispatch_kind(vt);
    /* BUG-1212: a `?*T` / `?funcptr` is a null-sentinel pointer — ONE word, the
     * same store as a `*T` (it is emitted as a plain C pointer). It was classified
     * an aggregate, so the published-pointer idiom `volatile ?*u32 gp = null;`
     * shared with an ISR was refused as "not a single-word scalar". */
    if (k == TYPE_OPTIONAL && type_is_null_sentinel(vt->optional.inner))
        k = TYPE_POINTER;
    bool scalar = type_is_integer(vt) || k == TYPE_BOOL || k == TYPE_POINTER;
    if (!scalar) return false;          /* aggregate — never one word */
    /* 2026-08-06: a POINTER is admitted to the scalar set above, but
     * type_width() has NO TYPE_POINTER case and returns 0 via its default — so
     * `w <= 0` rejected every volatile pointer global and the exemption never
     * applied to one. A `volatile *T` shared with a spawned thread was falsely
     * flagged as a data race (regression from a3d8879f, found by branch 2sjyjj).
     *
     * Fixed HERE rather than in type_width(): that helper has 39 call sites
     * including integer PROMOTION (`type_width(a) >= type_width(b)`) and bit-slice
     * index validation (`zer_bit_index_valid(type_width(obj), hi)`). Giving
     * pointers a nonzero width there would silently make bit-slicing a pointer
     * "valid" and change promotion for pointer operands. Do not "fix" type_width
     * globally without auditing all 39. A pointer is exactly one target word by
     * definition, which is all this predicate needs. */
    int w = (k == TYPE_POINTER) ? c->target_ptr_bits : type_width(vt);
    if (w <= 0) return false;
    if (w > c->target_ptr_bits) return false;
    /* BUG-1249: the exemption covers the POINTER WORD, and the scan cannot tell a
     * read of the word from a dereference of it — so `volatile ?*T gp = &obj;`
     * exempted every `p.v += 1` through it, a race on `obj` (TSan-confirmed; the
     * heap-object sibling made GCC spin forever on the main side). A pointer is
     * exempt only when what it points at is itself synchronised: volatile, or a
     * shared struct. The rationale's qualifier ("single-word flag") is about the
     * word; the pointee was never covered by it. */
    if (k == TYPE_POINTER) {
        Type *pt = vt;
        if (type_dispatch_kind(pt) == TYPE_OPTIONAL) pt = type_unwrap_distinct(pt->optional.inner);
        if (!pt || type_dispatch_kind(pt) != TYPE_POINTER) return true;   /* funcptr */
        if (pt->pointer.is_volatile) return true;
        Type *pe = type_unwrap_distinct(pt->pointer.inner);
        return pe && type_dispatch_kind(pe) == TYPE_STRUCT &&
               (pe->struct_type.is_shared || pe->struct_type.is_shared_rw);
    }
    return true;
}

static bool type_carries_nonshared_pointer(Type *t, int depth) {
    if (depth > 32) return true;   /* BUG-976: unknown -> assume it carries one */
    if (!t) return false;
    TypeKind k = type_dispatch_kind(t);
    Type *u = type_unwrap_distinct(t);
    if (!u) return false;
    if (k == TYPE_POINTER) {
        Type *inner = type_unwrap_distinct(u->pointer.inner);
        if (inner && inner->kind == TYPE_STRUCT && inner->struct_type.is_shared)
            return false;              /* pointer to shared struct — auto-locked */
        return true;
    }
    if (k == TYPE_SLICE || k == TYPE_OPAQUE) return true;
    if (k == TYPE_OPTIONAL)
        return type_carries_nonshared_pointer(u->optional.inner, depth + 1);
    if (k == TYPE_ARRAY)
        return type_carries_nonshared_pointer(u->array.inner, depth + 1);
    if (k == TYPE_STRUCT) {
        for (uint32_t i = 0; i < u->struct_type.field_count; i++) {
            if (type_carries_nonshared_pointer(u->struct_type.fields[i].type, depth + 1))
                return true;
        }
        return false;
    }
    if (k == TYPE_UNION) {
        for (uint32_t i = 0; i < u->union_type.variant_count; i++) {
            if (type_carries_nonshared_pointer(u->union_type.variants[i].type, depth + 1))
                return true;
        }
        return false;
    }
    return false;
}
#include <math.h>

/* ================================================================
 * ZER Type Checker — walks AST, resolves types, checks correctness
 *
 * Architecture:
 *   1. First pass: register all top-level declarations (structs, enums,
 *      unions, typedefs, functions, globals) into global scope.
 *   2. Second pass: type-check all function bodies.
 *
 * This two-pass approach allows forward references (function A calls
 * function B defined later in the file).
 * ================================================================ */

/* ---- Error reporting ---- */

/* Print the source line and a caret underline for the error location.
 * If source is NULL, does nothing. */
static void print_source_line(FILE *out, const char *source, int line) {
    if (!source || line < 1) return;
    /* find line N (1-based) */
    const char *p = source;
    for (int cur = 1; cur < line && *p; cur++) {
        while (*p && *p != '\n') p++;
        if (*p == '\n') p++;
    }
    if (!*p) return;
    /* find end of line */
    const char *end = p;
    while (*end && *end != '\n' && *end != '\r') end++;
    int len = (int)(end - p);
    if (len == 0) return;
    /* find first non-whitespace for caret position */
    int first_nonws = 0;
    while (first_nonws < len && (p[first_nonws] == ' ' || p[first_nonws] == '\t'))
        first_nonws++;
    int content_len = len - first_nonws;
    if (content_len <= 0) return;
    /* H2 (2026-08-02): CAP the echoed line. It was printed in FULL, once per
     * error, so a file with one very long line cost O(errors x line_len) — a
     * quadratic compile-time DoS. Measured on main: 1200 undeclared idents on a
     * single 32 KB line produced 2401 errors and **78 MB** of stderr in 2.1 s;
     * the tracker records ~20 s on an 80 KB line. The caret run below was
     * already capped at 60, so only the echo was unbounded.
     *
     * 200 chars keeps every realistic line intact (the longest line in this
     * repo's own sources is well under it) and bounds the pathological case. */
    int echo_len = len;
    bool echo_truncated = false;
    if (echo_len > 200) { echo_len = 200; echo_truncated = true; }
    /* print: " line | source_text" */
    fprintf(out, " %4d | %.*s%s\n", line, echo_len, p,
            echo_truncated ? " ..." : "");
    /* print: "      | ^^^^..." under the content */
    fprintf(out, "      | ");
    for (int i = 0; i < first_nonws; i++)
        fputc(p[i] == '\t' ? '\t' : ' ', out);
    for (int i = 0; i < content_len && i < 60; i++)
        fputc('^', out);
    fputc('\n', out);
}

static void checker_add_diag(Checker *c, int line, int severity, const char *fmt, va_list ap) {
    if (c->diag_count >= c->diag_capacity) {
        int new_cap = c->diag_capacity * 2;
        if (new_cap < 32) new_cap = 32;
        Diagnostic *new_d = (Diagnostic *)realloc(c->diagnostics, new_cap * sizeof(Diagnostic));
        if (new_d) { c->diagnostics = new_d; c->diag_capacity = new_cap; }
    }
    if (c->diag_count < c->diag_capacity) {
        Diagnostic *d = &c->diagnostics[c->diag_count++];
        d->line = line;
        d->severity = severity;
        vsnprintf(d->message, sizeof(d->message), fmt, ap);
    }
}

static void checker_error(Checker *c, int line, const char *fmt, ...) {
    c->error_count++;
    va_list args;
    va_start(args, fmt);
    checker_add_diag(c, line, 1, fmt, args);
    va_end(args);
    fprintf(stderr, "%s:%d: error: ", c->file_name, line);
    va_start(args, fmt);
    vfprintf(stderr, fmt, args);
    va_end(args);
    fprintf(stderr, "\n");
    print_source_line(stderr, c->source, line);
}

static void checker_warning(Checker *c, int line, const char *fmt, ...) {
    c->warning_count++;
    va_list args;
    va_start(args, fmt);
    checker_add_diag(c, line, 2, fmt, args);
    va_end(args);
    fprintf(stderr, "%s:%d: warning: ", c->file_name, line);
    va_start(args, fmt);
    vfprintf(stderr, fmt, args);
    va_end(args);
    fprintf(stderr, "\n");
    print_source_line(stderr, c->source, line);
}

/* ---- Non-storable tracking ----
 * pool.get(h) returns a non-storable result.
 * BUG-346: moved from static globals into Checker struct for thread safety. */

/* ---- Handle auto-deref: find unique Slab/Pool for a Handle's element type ---- */
Symbol *find_unique_allocator(Scope *s, Type *elem_type) {
    Symbol *found = NULL;
    for (Scope *sc = s; sc; sc = sc->parent) {
        for (uint32_t i = 0; i < sc->symbol_count; i++) {
            Type *t = sc->symbols[i]->type;
            if (!t) continue;
            if ((t->kind == TYPE_SLAB && type_equals(t->slab.elem, elem_type)) ||
                (t->kind == TYPE_POOL && type_equals(t->pool.elem, elem_type))) {
                /* BUG-416 fix: imported module globals are registered under both
                 * raw name ("cross_world") and mangled name ("cross_entity__cross_world")
                 * in the global scope (BUG-233). Both point to the same Type*.
                 * Don't treat these as ambiguous — same Type* = same allocator. */
                if (found && found->type == t) continue; /* same allocator, skip */
                if (found) return NULL; /* genuinely different allocator — ambiguous */
                found = sc->symbols[i];
            }
        }
    }
    return found;
}

static void non_storable_init(Checker *c) {
    c->non_storable_capacity = 64;
    c->non_storable_nodes = (Node **)arena_alloc(c->arena, c->non_storable_capacity * sizeof(Node *));
    c->non_storable_count = 0;
}

static void mark_non_storable(Checker *c, Node *n) {
    if (c->non_storable_count >= c->non_storable_capacity) {
        int new_cap = c->non_storable_capacity * 2;
        Node **new_arr = (Node **)arena_alloc(c->arena, new_cap * sizeof(Node *));
        memcpy(new_arr, c->non_storable_nodes, c->non_storable_count * sizeof(Node *));
        c->non_storable_nodes = new_arr;
        c->non_storable_capacity = new_cap;
    }
    c->non_storable_nodes[c->non_storable_count++] = n;
}

static bool type_carries_data_pointer(Type *t, int depth);
static bool is_non_storable_direct(Checker *c, Node *n) {
    for (int i = 0; i < c->non_storable_count; i++) {
        if (c->non_storable_nodes[i] == n) return true;
    }
    return false;
}
/* BUG-1255: "is a get() pointer stored by this value?" — the rule matched only a
 * BARE `pool.get(h)`, so `id(pool.get(h))`, `(*T)pool.get(h)`, `@ptrcast` /
 * `@pun`, an `orelse`, a `*opaque` round trip and a struct literal field all
 * stored the pointer, and after `pool.free(h)` + a new alloc it read the reused
 * slot (returned 99). A call is conservative: its result may be a view of the
 * get() argument. A FIELD read of a get() (`pool.get(h).v`) reads a value and is
 * not descended — the site's own type gate decides whether the value can hold a
 * pointer. */
static bool is_non_storable_depth(Checker *c, Node *n, int depth) {
    if (!n || depth > ZER_EXPR_WALK_MAX) return false;
    if (depth > 0) {
        /* a nested value that cannot hold a pointer cannot carry the slot
         * pointer onward (`v2_add(e.pos, …)` reads a Vec2 by value) */
        Type *nt = checker_get_type(c, n);
        if (!nt || !type_carries_data_pointer(nt, 0)) return false;   /* unknown: a value read */
    }
    if (is_non_storable_direct(c, n)) return true;
    switch (n->kind) {
    case NODE_TYPECAST: return is_non_storable_depth(c, n->typecast.expr, depth + 1);
    case NODE_ORELSE:
        return is_non_storable_depth(c, n->orelse.expr, depth + 1) ||
               is_non_storable_depth(c, n->orelse.fallback, depth + 1);
    case NODE_CALL:
        for (int i = 0; i < n->call.arg_count; i++)
            if (is_non_storable_depth(c, n->call.args[i], depth + 1)) return true;
        return false;
    case NODE_INTRINSIC:
        for (int i = 0; i < n->intrinsic.arg_count; i++)
            if (is_non_storable_depth(c, n->intrinsic.args[i], depth + 1)) return true;
        return false;
    case NODE_STRUCT_INIT:
        for (int i = 0; i < n->struct_init.field_count; i++)
            if (is_non_storable_depth(c, n->struct_init.fields[i].value, depth + 1)) return true;
        return false;
    /* a value read out of it, an operator result, a leaf or a statement kind */
    case NODE_FIELD: case NODE_INDEX: case NODE_SLICE: case NODE_UNARY:
    case NODE_BINARY: case NODE_ASSIGN: case NODE_IDENT: case NODE_INT_LIT:
    case NODE_FLOAT_LIT: case NODE_STRING_LIT: case NODE_CHAR_LIT: case NODE_BOOL_LIT:
    case NODE_NULL_LIT: case NODE_CAST: case NODE_SIZEOF:
    case NODE_FILE: case NODE_FUNC_DECL: case NODE_STRUCT_DECL: case NODE_ENUM_DECL:
    case NODE_UNION_DECL: case NODE_TYPEDEF: case NODE_IMPORT: case NODE_CINCLUDE:
    case NODE_INTERRUPT: case NODE_MMIO: case NODE_GLOBAL_VAR: case NODE_CONTAINER_DECL:
    case NODE_VAR_DECL: case NODE_BLOCK: case NODE_IF: case NODE_FOR: case NODE_WHILE:
    case NODE_SWITCH: case NODE_RETURN: case NODE_BREAK: case NODE_CONTINUE:
    case NODE_DEFER: case NODE_GOTO: case NODE_LABEL: case NODE_EXPR_STMT:
    case NODE_ASM: case NODE_CRITICAL: case NODE_ONCE: case NODE_SPAWN:
    case NODE_YIELD: case NODE_AWAIT: case NODE_DO_WHILE: case NODE_STATIC_ASSERT:
        return false;
    }
    return false;
}
static bool is_non_storable(Checker *c, Node *n) {
    if (!n) return false;
    if (is_non_storable_direct(c, n)) return true;   /* the bare get(): old rule */
    /* a WRAPPER stores the slot pointer only if its own value can hold one */
    Type *nt = checker_get_type(c, n);
    if (nt && !type_carries_data_pointer(nt, 0)) return false;
    return is_non_storable_depth(c, n, 0);
}

/* ---- Scope helpers ---- */

static void push_scope(Checker *c) {
    c->current_scope = scope_new(c->arena, c->current_scope);
}

static void pop_scope(Checker *c) {
    c->current_scope = c->current_scope->parent;
}

static Symbol *add_symbol_internal(Checker *c, const char *name, uint32_t name_len,
                                   Type *type, int line) {
    /* Internal: no _zer_ prefix check — used for compiler-generated symbols */
    Symbol *sym = scope_add(c->arena, c->current_scope, name, name_len,
                            type, line, c->file_name);
    return sym;
}

/* Internal: add_symbol implementation parameterized by reserved-prefix
 * enforcement. Public wrapper add_symbol() always enforces; the synthetic
 * variant add_symbol_synth() bypasses for parser-emitted desugaring (Gap 30). */
/* BUG-1120: THE lookup of a top-level name. Inside an imported module whose
 * global / function shares its raw name with another module's, the raw
 * global-scope entry is the OTHER module's (first registration wins); this
 * module's own Symbol lives in `module_own`. Every checker site that used to
 * read `c->global_scope` directly (120 of them — callee resolution, spawn
 * targets, ISR descents, FuncProps, summaries) got the other module's
 * declaration, so module b's `bump()` was scanned, summarised and typed as
 * module a's. Outside that case this is exactly scope_lookup_local on the
 * global scope. */
static Symbol *global_decl_lookup(Checker *c, const char *name, uint32_t len) {
    if (c->current_module) {
        for (int mi = 0; mi < c->module_own_count; mi++) {
            Symbol *ms = c->module_own[mi].sym;
            if (ms && ms->name_len == len && memcmp(ms->name, name, len) == 0 &&
                ms->module_prefix_len == c->current_module_len && ms->module_prefix &&
                memcmp(ms->module_prefix, c->current_module, c->current_module_len) == 0)
                return ms;
        }
    }
    return scope_lookup_local(c->global_scope, name, len);
}

/* BUG-1199: an analysis that DESCENDS into another function's body (the spawn
 * race scan, the ISR walk, the callee-globals walk, the shared-type collector)
 * must resolve that body's names in the body's OWN module. `global_decl_lookup`
 * answers relative to `c->current_module`, and every scan runs from the caller's
 * context — so walking module m's `bump()` from main looked `cnt` up as MAIN
 * would: a module `static` (registered only in m's scope) resolved to nothing and
 * a name m shares with another module resolved to the other module's. Measured:
 * two threads doing `scnt += 1` on an imported static compiled clean and lost
 * updates; a Pool touched from a spawn and an ISR the same. Enter the callee's
 * module for the descent and restore after. */
typedef struct { const char *mod; uint32_t len; } DeclModuleSave;
static DeclModuleSave decl_module_enter(Checker *c, Symbol *fs) {
    DeclModuleSave sv = { c->current_module, c->current_module_len };
    if (fs) { c->current_module = fs->module_prefix; c->current_module_len = fs->module_prefix_len; }
    return sv;
}
static void decl_module_leave(Checker *c, DeclModuleSave sv) {
    c->current_module = sv.mod; c->current_module_len = sv.len;
}

static Symbol *add_symbol_impl(Checker *c, const char *name, uint32_t name_len,
                               Type *type, int line, bool enforce_reserved) {
    /* BUG-276: warn on _zer_ prefixed names — reserved for compiler internals */
    if (enforce_reserved && name_len >= 5 && memcmp(name, "_zer_", 5) == 0) {
        checker_error(c, line,
            "identifier '%.*s' uses reserved prefix '_zer_' — "
            "may collide with compiler-generated names",
            (int)name_len, name);
    }
    Symbol *sym = scope_add(c->arena, c->current_scope, name, name_len,
                            type, line, c->file_name);
    if (sym) sym->decl_branch_depth = c->branch_depth;   /* BUG-1274 */
    if (!sym) {
        /* check if this is a cross-module type collision — give helpful error */
        Symbol *existing = scope_lookup(c->current_scope, name, name_len);
        if (existing && existing->type && type && c->current_module) {
            const char *existing_mod = NULL;
            Type *et = type_unwrap_distinct(existing->type);
            if (et->kind == TYPE_STRUCT) existing_mod = et->struct_type.module_prefix;
            else if (et->kind == TYPE_ENUM) existing_mod = et->enum_type.module_prefix;
            else if (et->kind == TYPE_UNION) existing_mod = et->union_type.module_prefix;

            if (existing_mod != c->current_module) {
                /* cross-module type collision — allowed, per-module scope resolves it.
                 * First registration wins in global scope; module scope overrides. */
                existing->cross_module_dup = true;   /* BUG-1200 */
                return existing;
            }
        }
        checker_error(c, line, "redefinition of '%.*s'", (int)name_len, name);
    }
    return sym;
}

/* Public: enforces reserved prefix (rejects user-declared _zer_*). */
static Symbol *add_symbol(Checker *c, const char *name, uint32_t name_len,
                          Type *type, int line) {
    return add_symbol_impl(c, name, name_len, type, line, true);
}

/* Public: bypasses reserved-prefix check — used by parser-synthesized
 * desugaring (e.g., range-for _zer_ri). User-source code should always
 * use add_symbol(). */
static Symbol *add_symbol_synth(Checker *c, const char *name, uint32_t name_len,
                                Type *type, int line) {
    Symbol *s = add_symbol_impl(c, name, name_len, type, line, false);
    if (s) s->is_synthetic_var = true;   /* BUG-1099 */
    return s;
}

/* BUG-1200: does this lookup result stand for TWO imported modules' declarations?
 * Two modules may each declare a top-level `get` / `total` / `Pt`; the raw
 * global-scope entry is whichever registered first, and each module's own body
 * sees its own through the module scope. Code that owns NEITHER (main, or a third
 * module) reached the first registration by lookup order alone — measured: main
 * calling `get()` with c and d both defining it silently called c's, and
 * `Pt p; p.x = 300;` silently used c's layout. Reaching the flagged raw entry from
 * a module that does not own it is an ambiguity, not a choice to make silently. */
static const char *symbol_owner_module(Symbol *s, uint32_t *len) {
    /* functions and globals carry their module; a TYPE name's Symbol does not,
     * its Type does */
    if (s->module_prefix) { *len = s->module_prefix_len; return s->module_prefix; }
    Type *t = s->type ? type_unwrap_distinct(s->type) : NULL;
    TypeKind k = type_dispatch_kind(t);
    if (k == TYPE_STRUCT) { *len = t->struct_type.module_prefix_len; return t->struct_type.module_prefix; }
    if (k == TYPE_ENUM)   { *len = t->enum_type.module_prefix_len;   return t->enum_type.module_prefix; }
    if (k == TYPE_UNION)  { *len = t->union_type.module_prefix_len;  return t->union_type.module_prefix; }
    *len = 0;
    return NULL;
}
/* BUG-1200: a qualified `mod.name` is rewritten to the bare `name`, and every
 * later stage (the checker's own lookups, the emitter) resolves the bare name.
 * That is only right when the bare name resolves, from here, to MOD's
 * declaration. When another module's same-named declaration is what the bare
 * name reaches, the rewrite silently retargets the reference — measured:
 * `d.get()` called c's get(), `d.shared_name = 50` wrote c's. */
static bool qualified_rewrite_retargets(Checker *c, const char *mod, uint32_t mod_len,
                                        const char *name, uint32_t name_len) {
    Symbol *bare = scope_lookup(c->current_scope, name, name_len);
    if (!bare) return false;
    uint32_t ol = 0;
    const char *om = symbol_owner_module(bare, &ol);
    return !(om && ol == mod_len && memcmp(om, mod, mod_len) == 0);
}
static void report_qualified_retarget(Checker *c, const char *mod, uint32_t mod_len,
                                      const char *name, uint32_t name_len, int line) {
    checker_error(c, line,
        "'%.*s.%.*s': another imported module also declares '%.*s', and a qualified "
        "reference to the SECOND declaration of a shared name is not supported yet "
        "(it would silently reach the first). Rename one of them",
        (int)mod_len, mod, (int)name_len, name, (int)name_len, name);
}
static bool symbol_is_import_ambiguous(Checker *c, Symbol *s) {
    if (!s || !s->cross_module_dup) return false;
    if (scope_lookup_local(c->global_scope, s->name, s->name_len) != s) return false;
    uint32_t ol = 0;
    const char *om = symbol_owner_module(s, &ol);
    if (om && c->current_module && ol == c->current_module_len &&
        memcmp(om, c->current_module, ol) == 0) return false;
    return true;
}
static void report_import_ambiguous(Checker *c, Symbol *s, int line) {
    checker_error(c, line,
        "'%.*s' is declared by more than one imported module — this reference "
        "does not say which, and silently taking the first-registered one is how "
        "a call reached the wrong module. Rename one of the declarations",
        (int)s->name_len, s->name);
}

static Symbol *find_symbol(Checker *c, const char *name, uint32_t name_len, int line) {
    Symbol *sym = scope_lookup(c->current_scope, name, name_len);
    if (!sym) {
        checker_error(c, line, "undefined identifier '%.*s'", (int)name_len, name);
    }
    return sym;
}

/* ---- Node type storage ----
 * We store the resolved Type* for each expression node in a simple
 * hash map keyed by node pointer. This avoids modifying the Node struct. */

/* ---- Dynamic type map: open-addressing hash, grows when >70% full ---- */
/* RF1: typemap is now per-Checker (fields in Checker struct), not global */

#define TYPE_MAP_INIT_SIZE 4096

static void typemap_init(Checker *c) {
    c->type_map_size = TYPE_MAP_INIT_SIZE;
    c->type_map = (TypeMapEntry *)arena_alloc(c->arena, c->type_map_size * sizeof(TypeMapEntry));
    c->type_map_count = 0;
}

static void typemap_grow(Checker *c) {
    uint32_t old_size = c->type_map_size;
    TypeMapEntry *old_map = c->type_map;
    c->type_map_size = old_size * 2;
    c->type_map = (TypeMapEntry *)arena_alloc(c->arena,
        c->type_map_size * sizeof(TypeMapEntry));
    c->type_map_count = 0;
    for (uint32_t i = 0; i < old_size; i++) {
        if (old_map[i].key) {
            uint32_t idx = ((uintptr_t)old_map[i].key >> 3) % c->type_map_size;
            for (uint32_t j = 0; j < c->type_map_size; j++) {
                uint32_t slot = (idx + j) % c->type_map_size;
                if (!c->type_map[slot].key) {
                    c->type_map[slot] = old_map[i];
                    c->type_map_count++;
                    break;
                }
            }
        }
    }
}

static void typemap_set(Checker *c, Node *node, Type *type) {
    if (c->type_map_count * 10 > c->type_map_size * 7) {
        typemap_grow(c);
    }
    uint32_t idx = ((uintptr_t)node >> 3) % c->type_map_size;
    for (uint32_t i = 0; i < c->type_map_size; i++) {
        uint32_t slot = (idx + i) % c->type_map_size;
        if (!c->type_map[slot].key) {
            c->type_map[slot].key = node;
            c->type_map[slot].type = type;
            c->type_map_count++;
            return;
        }
        if (c->type_map[slot].key == node) {
            c->type_map[slot].type = type;
            return;
        }
    }
}

static Type *typemap_get(Checker *c, Node *node) {
    if (!c->type_map) return NULL;
    uint32_t idx = ((uintptr_t)node >> 3) % c->type_map_size;
    for (uint32_t i = 0; i < c->type_map_size; i++) {
        uint32_t slot = (idx + i) % c->type_map_size;
        if (c->type_map[slot].key == node) return c->type_map[slot].type;
        if (!c->type_map[slot].key) return NULL;
    }
    return NULL;
}

